"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Toggle as TogglePrimitive } from "radix-ui";

import { cn } from "../lib/utils";

import geometry from "./button-geometry.module.css";
import material from "./button-material.module.css";
import controlStyles from "./controls.module.css";

const toggleVariants = cva(
  [
    geometry.button,
    controlStyles.focusOutline,
    controlStyles.toggle,
    material.paintTransition,
    material.neutralSelection,
    "group/toggle inline-flex items-center justify-center whitespace-nowrap [&_svg]:pointer-events-none [&_svg]:shrink-0"
  ],
  {
    variants: {
      variant: {
        outline: controlStyles.toggleOutline,
        default: controlStyles.toggleOutline,
        ghost: controlStyles.toggleGhost
      },
      size: {
        default: geometry.default,
        sm: geometry.default,
        md: geometry.regular,
        lg: geometry.large
      }
    },
    defaultVariants: {
      variant: "outline",
      size: "default"
    }
  }
);

function Toggle({
  className,
  variant = "outline",
  size = "default",
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof TogglePrimitive.Root> &
  VariantProps<typeof toggleVariants> & {
    ref?: React.Ref<React.ComponentRef<typeof TogglePrimitive.Root>>;
    /** Toggle is a pressed button, not a switch. Use Switch for checked and onCheckedChange, or pressed here. */
    checked?: never;
    /** Toggle is a pressed button, not a switch. Use Switch for defaultChecked, or defaultPressed here. */
    defaultChecked?: never;
    /** Toggle is a pressed button, not a switch. Use Switch for checked and onCheckedChange, or onPressedChange here. */
    onCheckedChange?: never;
  }) {
  const { "data-state": _wrapperState, ...toggleProps } = props as typeof props & {
    "data-state"?: string;
  };
  return (
    <TogglePrimitive.Root
      ref={ref}
      data-variant={variant === "default" ? "outline" : variant}
      data-size={size}
      className={cn(toggleVariants({ variant, size, className }))}
      {...toggleProps}
      data-slot="toggle"
    >
      <span data-press="">{children}</span>
    </TogglePrimitive.Root>
  );
}
Toggle.displayName = "Toggle";

export { Toggle, toggleVariants };
